impl std::fmt::Display for Size {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Percent(p) => f.write_fmt(format_args!("{p}%")),
            Self::Fixed(s) => f.write_fmt(format_args!("{s}")),
            Self::Neg(s) => f.write_fmt(format_args!("-{s}")),
        }
    }
}

