pub enum BorderType {
    #[default]
    Plain,
    Rounded,
    Double,
    Thick,

    LightDoubleDashed,
    HeavyDoubleDashed,

    LightTripleDashed,
    HeavyTripleDashed,

    LightQuadrupleDashed,
    HeavyQuadrupleDashed,

    QuadrantInside,
    QuadrantOutside,
}

