        unsafe { std::env::set_var("COLUMNS", "80") };
        // 20 cols wide → end offset = 80 - 20 = 60
        assert_eq!(align_end_coord(Size::Fixed(20), "COLUMNS"), Size::Fixed(60));
        unsafe { std::env::remove_var("COLUMNS") };
    }

